let selected=0,stage=0,playing=false,mode='cpu',host=true,room='',game=null,local={},remote={},sound=false,audio=null;
const ctx=$('#fight').getContext('2d');
function rect(c,x,y,w,h,col){c.fillStyle=col;c.fillRect(Math.round(x),Math.round(y),w,h)}
function label(c,t,x,y,size=16,col='#fff',align='left'){c.fillStyle=col;c.font=`900 ${size}px monospace`;c.textAlign=align;c.fillText(t,x,y)}
function fighter(c,id,x,y,scale=1,dir=1,pose=0,t=0){const r=roster[id],walk=Math.sin(t*12)*4;c.save();c.translate(Math.round(x),Math.round(y));c.scale(scale*dir,scale);const skin='#d5a179',hair=id===0?'#52392d':id===3?'#bd5832':'#292837';rect(c,-23,0,46,7,'#0005');rect(c,-15,-44,12,40,r[2]);rect(c,4,-44,12,40,r[2]);rect(c,-18,-8+walk,19,8,'#252637');rect(c,2,-8-walk,21,8,'#252637');rect(c,-19,-84,38,44,r[2]);rect(c,-15,-113,30,31,skin);rect(c,-17,-118,34,12,hair);if(id===0){rect(c,-23,-108,11,38,hair);rect(c,-19,-84,9,15,hair);rect(c,-15,-81,31,5,'#eacb69')}if(id===1){rect(c,-4,-82,8,27,'#eee');rect(c,-2,-78,4,24,'#dd6c68');rect(c,-14,-111,28,4,hair)}if(id===4)rect(c,-20,-82,10,36,'#e6eeee');if(id===5)rect(c,-20,-120,40,8,r[2]);if(id===6){rect(c,-18,-128,35,17,'#eee');rect(c,-10,-136,19,15,'#eee')}rect(c,7,-104,4,4,'#20202b');rect(c,10,-92,7,3,'#a66658');const arm=pose>0?27:Math.sin(t*7)*3;rect(c,-26,-78,10,33,skin);rect(c,17,-78,12+arm,10,skin);rect(c,20+arm,-76,12,14,skin);if(pose===2){rect(c,10,-48,42,12,r[2]);rect(c,48,-48,14,12,'#252637')}if(pose===3){rect(c,22,-95,10,37,'#dfff6c')}c.restore()}
function background(c,s,w=960,h=500){c.save();c.scale(w/960,h/500);let g=c.createLinearGradient(0,0,0,500);g.addColorStop(0,s?'#22243f':'#71566b');g.addColorStop(1,s?'#695261':'#e6a475');c.fillStyle=g;c.fillRect(0,0,960,500);rect(c,708,55,65,65,s?'#e5dfb4':'#f6c98b');for(let i=0;i<14;i++){let x=i*83-30,y=190+(i*47%70);rect(c,x,y,91,240,i%2?'#58505a':'#786267');rect(c,x-4,y,98,8,'#3e3c4c');for(let k=0;k<3;k++){rect(c,x+12+k*26,y+27,13,18,s?'#e6b86b':'#342f43');rect(c,x+12+k*26,y+90,13,18,'#403a4a')}for(let b=0;b<5;b++)rect(c,x+8,y+15+b*35,65,2,'#9b777044')}c.strokeStyle='#24283a';c.lineWidth=3;for(let i=0;i<4;i++){c.beginPath();c.moveTo(0,90+i*15);c.quadraticCurveTo(480,180+i*12,960,100+i*15);c.stroke()}if(!s){rect(c,60,250,395,100,'#777c82');rect(c,60,243,395,15,'#4f5564');for(let i=0;i<6;i++){rect(c,75+i*61,265,43,35,'#283d53');rect(c,75+i*61,310,43,5,'#d5c681')}rect(c,0,350,960,12,'#b6a58e');rect(c,500,200,320,46,'#243f57');label(c,'VILLA RIOSA',660,232,27,'#e8eddb','center');rect(c,512,246,8,120,'#343c48');rect(c,800,246,8,120,'#343c48')}else{rect(c,290,255,385,63,'#404747');label(c,'SAN JORGE',480,284,24,'#e5d1a1','center');label(c,'DON TORCUATO',480,306,14,'#d2b6a2','center');rect(c,780,180,5,190,'#25283b');rect(c,765,180,40,6,'#c5bdb0');rect(c,774,185,20,12,'#ffdb88')}rect(c,0,369,960,131,'#383b49');rect(c,0,369,960,6,'#b4a68c');for(let i=0;i<16;i++)rect(c,i*72+12,413+(i%3)*21,30,3,'#575562');label(c,'AGUANTE',70,335,22,'#d8e46d');label(c,'EL BARRIO VIVE',815,348,13,'#debfbd','center');c.restore()}
function renderPoster(){let c=$('#poster').getContext('2d');background(c,0,600,330);fighter(c,0,180,295,1.7,1,1,0);fighter(c,1,430,295,1.7,-1,0,0);label(c,'LABURANTES, PERO BRAVOS.',300,36,16,'#f6f1df','center')}
function select(id){selected=id;document.querySelectorAll('.fighter').forEach((b,i)=>b.classList.toggle('active',i===id));let r=roster[id];$('#selectedName').textContent=r[0].toUpperCase();$('#bio').innerHTML=`<div><strong>${r[0]}</strong><p>${r[1]}</p></div><div class="powers">${r.slice(3).map((p,i)=>`<span>${i===3?'★ ULTI':`P${i+1}`} · ${p}</span>`).join('')}</div>`}
roster.forEach((r,i)=>{let b=document.createElement('button');b.className='fighter';b.setAttribute('aria-label',r[0]+', '+r[1]);b.innerHTML=`<canvas width="100" height="130"></canvas><span>${r[0]}</span>`;b.onclick=()=>select(i);$('#roster').append(b);fighter(b.querySelector('canvas').getContext('2d'),i,50,126,1,1,0,0)});select(0);renderPoster();
function say(t){if(!sound)return;beep(180,.12);if('speechSynthesis'in window){speechSynthesis.cancel();let u=new SpeechSynthesisUtterance(t);u.lang='es-AR';u.rate=1.06;speechSynthesis.speak(u)}}
function beep(f=220,d=.07){if(!sound)return;try{audio??=new (window.AudioContext||window.webkitAudioContext)();audio.resume();let o=audio.createOscillator(),g=audio.createGain();o.type='square';o.frequency.setValueAtTime(f,audio.currentTime);o.frequency.exponentialRampToValueAtTime(55,audio.currentTime+d);g.gain.setValueAtTime(.045,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+d);o.connect(g).connect(audio.destination);o.start();o.stop(audio.currentTime+d)}catch{}}
$('#sound').onclick=()=>{sound=!sound;$('#sound').textContent='SONIDO: '+(sound?'SÍ':'NO');beep()};
function fresh(id,x){return ArenaEngine.fresh(id,x)}
function start(){}



function step(){}
function showResult(){if(!game?.done)return;$('#result').hidden=false;$('#resultText').textContent=game.message}
function draw(now){if(!playing||!game)return;background(ctx,stage);game.p.forEach(p=>{let moving=p===game.p[host?0:1]?local.left||local.right:false;fighter(ctx,p.id,p.x,p.y,1.35,p.dir,p.guard?3:p.pose,moving?now/1000:now/2500)});for(let s of game.shots){ctx.fillStyle=s.color;ctx.globalAlpha=s.smoke?.6:1;ctx.beginPath();ctx.arc(s.x,s.y,s.r,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;label(ctx,['⚡','$','~','★'][s.kind],s.x,s.y+6,22,'#202438','center')}for(let f of game.fx){label(ctx,f.block?'CLANG':'PÁF',f.x,f.y-20,30,f.block?'#fff':'#e9ff8b','center')}game.p.forEach((p,i)=>{let x=i?560:30;rect(ctx,x,30,370,20,'#202432');rect(ctx,i?x+370*(1-p.hp/100):x,30,370*p.hp/100,20,p.hp<25?'#ff7752':'#dfff6c');label(ctx,roster[p.id][0].toUpperCase(),x,23,16);label(ctx,'●'.repeat(p.wins)+'○'.repeat(2-p.wins),x,70,18,'#ffbe70');rect(ctx,x,76,370,7,'#222436');rect(ctx,x,76,p.en/100*370,7,'#b4a2ff');label(ctx,p.en>=100?'ULTI LISTA ★':`ENERGÍA ${Math.floor(p.en)}%`,x,101,11,'#d5c7fa')});label(ctx,String(Math.max(0,Math.ceil(game.time))).padStart(2,'0'),480,59,36,'#f6f1df','center');label(ctx,'R'+Math.min(game.round,5),480,82,12,'#ffb07a','center');if(game.message){rect(ctx,100,155,760,55,'#111321ce');label(ctx,game.message,480,190,game.message.length>30?20:27,'#f0ffd0','center')}let own=game.p[host?0:1];document.querySelectorAll('[data-key]').forEach(b=>{let k=b.dataset.key;if(/^p[012]$/.test(k)){let cd=own.cool[+k[1]];b.textContent=cd>0?'P'+(+k[1]+1)+' '+cd.toFixed(1):'P'+(+k[1]+1)}if(k==='ult')b.style.opacity=own.en>=100?'1':'.45'});showResult()}
function loop(now){requestAnimationFrame(loop)}requestAnimationFrame(loop);

document.querySelectorAll('[data-key]').forEach(b=>{const k=b.dataset.key;b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);local[k]=true;b.classList.add('held');beep(70,.02)};let release=()=>{local[k]=false;b.classList.remove('held')};b.onpointerup=release;b.onpointercancel=release;b.onlostpointercapture=release});const keys={a:'left',d:'right',w:'jump',s:'block',j:'punch',k:'kick',u:'p0',i:'p1',o:'p2',l:'ult'};window.addEventListener('keydown',e=>{if(playing&&keys[e.key.toLowerCase()]){e.preventDefault();local[keys[e.key.toLowerCase()]]=true}});window.addEventListener('keyup',e=>{if(keys[e.key.toLowerCase()])local[keys[e.key.toLowerCase()]]=false});window.addEventListener('blur',()=>{local={}});document.addEventListener('visibilitychange',()=>{local={};});
